# bash completion for godot-cli — generated by `godot-cli completions bash`.
#
# Install: source this file from ~/.bashrc, or copy it into
# /usr/local/etc/bash_completion.d/ (Homebrew) or /etc/bash_completion.d/.

_godot_cli_children() {
    case "$1" in
        '')
            echo "help ping uid scene resource catalog batch project completions man reference"
            ;;
        'uid')
            echo "encode decode create-for-path scene-id cache session"
            ;;
        'uid scene-id')
            echo "generate"
            ;;
        'uid cache')
            echo "list lookup"
            ;;
        'uid session')
            echo "import"
            ;;
        'scene')
            echo "new refs ext sub inspect node connection instance template plan apply diff restore validate validate-batch set-property normalize retarget-ext round-trip compare-godot"
            ;;
        'scene ext')
            echo "add remove"
            ;;
        'scene sub')
            echo "add remove"
            ;;
        'scene node')
            echo "list get add remove rename reparent"
            ;;
        'scene connection')
            echo "list add remove"
            ;;
        'scene instance')
            echo "add"
            ;;
        'scene template')
            echo "list show copy"
            ;;
        'resource')
            echo "inspect validate validate-batch set-property normalize retarget-ext round-trip compare-godot"
            ;;
        'catalog')
            echo "add relink scan list show validate search export"
            ;;
        'project')
            echo "show apply input settings autoload plugins rendering physics"
            ;;
        'project input')
            echo "list apply validate"
            ;;
        'project settings')
            echo "list get set apply validate"
            ;;
        'project autoload')
            echo "list apply validate"
            ;;
        'project plugins')
            echo "list enable disable apply validate"
            ;;
        'project rendering')
            echo "list apply validate"
            ;;
        'project physics')
            echo "list apply validate"
            ;;
        *)
            echo ""
            ;;
    esac
}

