_godot_cli_global_options="--help --version --json --verbose --request --request-file --request-stdin"

_godot_cli() {
    local cur path="" word children candidates
    COMPREPLY=()
    cur="${COMP_WORDS[COMP_CWORD]}"

    local index
    for (( index = 1; index < COMP_CWORD; index++ )); do
        word="${COMP_WORDS[index]}"
        case "$word" in
            -*) continue ;;
        esac
        children=" $(_godot_cli_children "$path") "
        if [[ "$children" == *" $word "* ]]; then
            path="${path:+$path }$word"
        fi
    done

    candidates="$(_godot_cli_children "$path") $(_godot_cli_options "$path") $_godot_cli_global_options"
    COMPREPLY=( $(compgen -W "$candidates" -- "$cur") )

    # Leaf commands nearly all take a path; offer files once the word
    # being completed is clearly not a flag.
    if [[ "$cur" != -* ]] && _godot_cli_takes_args "$path"; then
        COMPREPLY+=( $(compgen -f -- "$cur") )
    fi
}

complete -F _godot_cli godot-cli
